package vault

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"sync"

	"golang.org/x/crypto/scrypt"
)

const (
	vaultDir    = "/var/lib/securevault/data"
	tempDir     = "/var/lib/securevault/tmp"
	maxKeyLen   = 64
	maxValueLen = 4096

	// scrypt parameters (interactive/strong defaults)
	scryptN    = 1 << 15
	scryptR    = 8
	scryptP    = 1
	scryptKLen = 32
	saltLen    = 16
)

type SecureVault struct {
	mu        sync.RWMutex
	masterKey [32]byte
	nonceSize int
	gcm       cipher.AEAD
}

// NewSecureVault derives a master key from the passphrase using a salted,
// high-cost KDF (scrypt). The salt must be stable so the vault can be reopened;
// it is stored (created if absent) alongside the vault data with restrictive
// permissions.
func NewSecureVault(passphrase string) (*SecureVault, error) {
	v := &SecureVault{}

	if err := os.MkdirAll(vaultDir, 0700); err != nil {
		return nil, err
	}
	if err := os.MkdirAll(tempDir, 0700); err != nil {
		return nil, err
	}

	salt, err := loadOrCreateSalt()
	if err != nil {
		return nil, fmt.Errorf("salt init: %w", err)
	}

	derived, err := scrypt.Key([]byte(passphrase), salt, scryptN, scryptR, scryptP, scryptKLen)
	if err != nil {
		return nil, fmt.Errorf("kdf: %w", err)
	}
	copy(v.masterKey[:], derived)

	block, err := aes.NewCipher(v.masterKey[:])
	if err != nil {
		return nil, fmt.Errorf("cipher init: %w", err)
	}

	v.gcm, err = cipher.NewGCM(block)
	if err != nil {
		return nil, fmt.Errorf("gcm init: %w", err)
	}
	v.nonceSize = v.gcm.NonceSize()

	return v, nil
}

func loadOrCreateSalt() ([]byte, error) {
	saltPath := filepath.Join(vaultDir, ".salt")
	if data, err := os.ReadFile(saltPath); err == nil {
		if len(data) != saltLen {
			return nil, fmt.Errorf("invalid salt length")
		}
		return data, nil
	}

	salt := make([]byte, saltLen)
	if _, err := io.ReadFull(rand.Reader, salt); err != nil {
		return nil, err
	}
	if err := os.WriteFile(saltPath, salt, 0600); err != nil {
		return nil, err
	}
	return salt, nil
}

func (v *SecureVault) sanitizeKey(key string) (string, error) {
	if len(key) == 0 || len(key) > maxKeyLen {
		return "", fmt.Errorf("invalid key length")
	}
	for _, c := range key {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_') {
			return "", fmt.Errorf("invalid character in key: %c", c)
		}
	}
	return key, nil
}

func (v *SecureVault) resolveStoragePath(key string) (string, error) {
	sanitized, err := v.sanitizeKey(key)
	if err != nil {
		return "", err
	}
	hashed := sha256.Sum256([]byte(sanitized))
	filename := hex.EncodeToString(hashed[:16])
	fullPath := filepath.Join(vaultDir, filename+".enc")

	// Verify the resolved path is within vault directory
	resolved, err := filepath.Abs(fullPath)
	if err != nil {
		return "", err
	}
	vaultAbs, err := filepath.Abs(vaultDir)
	if err != nil {
		return "", err
	}
	// Require the resolved path to be strictly inside the vault directory,
	// guarding against sibling-directory prefix matches (e.g. "data-evil").
	if resolved != vaultAbs && !strings.HasPrefix(resolved, vaultAbs+string(os.PathSeparator)) {
		return "", fmt.Errorf("path traversal detected")
	}
	return resolved, nil
}

func (v *SecureVault) encrypt(plaintext []byte) ([]byte, error) {
	nonce := make([]byte, v.nonceSize)
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	return v.gcm.Seal(nonce, nonce, plaintext, nil), nil
}

func (v *SecureVault) decrypt(ciphertext []byte) ([]byte, error) {
	if len(ciphertext) < v.nonceSize {
		return nil, fmt.Errorf("ciphertext too short")
	}
	nonce, ct := ciphertext[:v.nonceSize], ciphertext[v.nonceSize:]
	return v.gcm.Open(nil, nonce, ct, nil)
}

func (v *SecureVault) atomicWrite(destPath string, data []byte) error {
	// Create temp file in temp directory
	tmpFile, err := os.CreateTemp(tempDir, "vault-*.tmp")
	if err != nil {
		return fmt.Errorf("create temp: %w", err)
	}
	tmpPath := tmpFile.Name()

	defer func() {
		if err != nil {
			os.Remove(tmpPath)
		}
	}()

	if _, err = tmpFile.Write(data); err != nil {
		tmpFile.Close()
		return fmt.Errorf("write temp: %w", err)
	}
	if err = tmpFile.Sync(); err != nil {
		tmpFile.Close()
		return fmt.Errorf("sync temp: %w", err)
	}
	tmpFile.Close()

	if err = os.Chmod(tmpPath, 0600); err != nil {
		return fmt.Errorf("chmod: %w", err)
	}

	// Verify destination is not a symlink before writing
	if info, statErr := os.Lstat(destPath); statErr == nil {
		if info.Mode()&os.ModeSymlink != 0 {
			os.Remove(tmpPath)
			return fmt.Errorf("symlink detected at destination")
		}
	}

	// Open destination with O_NOFOLLOW equivalent: remove and recreate
	os.Remove(destPath)
	destFile, err := os.OpenFile(destPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		os.Remove(tmpPath)
		return fmt.Errorf("create dest: %w", err)
	}

	tmpData, err := os.ReadFile(tmpPath)
	if err != nil {
		destFile.Close()
		os.Remove(destPath)
		os.Remove(tmpPath)
		return fmt.Errorf("read temp: %w", err)
	}

	if _, err = destFile.Write(tmpData); err != nil {
		destFile.Close()
		os.Remove(destPath)
		os.Remove(tmpPath)
		return fmt.Errorf("write dest: %w", err)
	}

	if err = destFile.Sync(); err != nil {
		destFile.Close()
		os.Remove(destPath)
		os.Remove(tmpPath)
		return fmt.Errorf("sync dest: %w", err)
	}
	destFile.Close()
	os.Remove(tmpPath)
	return nil
}

func (v *SecureVault) Store(key string, value []byte) error {
	v.mu.Lock()
	defer v.mu.Unlock()

	if len(value) > maxValueLen {
		return fmt.Errorf("value too large")
	}

	destPath, err := v.resolveStoragePath(key)
	if err != nil {
		return err
	}

	encrypted, err := v.encrypt(value)
	if err != nil {
		return fmt.Errorf("encrypt: %w", err)
	}

	return v.atomicWrite(destPath, encrypted)
}

func (v *SecureVault) Retrieve(key string) ([]byte, error) {
	v.mu.RLock()
	defer v.mu.RUnlock()

	storagePath, err := v.resolveStoragePath(key)
	if err != nil {
		return nil, err
	}

	// Check for symlink before reading
	info, err := os.Lstat(storagePath)
	if err != nil {
		return nil, fmt.Errorf("stat: %w", err)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return nil, fmt.Errorf("symlink detected")
	}

	data, err := os.ReadFile(storagePath)
	if err != nil {
		return nil, fmt.Errorf("read: %w", err)
	}

	return v.decrypt(data)
}

func (v *SecureVault) Delete(key string) error {
	v.mu.Lock()
	defer v.mu.Unlock()

	storagePath, err := v.resolveStoragePath(key)
	if err != nil {
		return err
	}

	// Check for symlink before deleting
	info, err := os.Lstat(storagePath)
	if err != nil {
		return fmt.Errorf("stat: %w", err)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("symlink detected")
	}

	return os.Remove(storagePath)
}
